VIEWER_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>TraceForge Viewer</title>
<style>
:root{color-scheme:dark;background:#081018;color:#e8f0f7;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#123047 0,#081018 34%,#05090e 100%);min-height:100vh}.shell{max-width:1450px;margin:auto;padding:24px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}.brand{display:flex;gap:12px;align-items:center}.mark{width:38px;height:38px;border:1px solid #2a6b87;border-radius:11px;display:grid;place-items:center;background:#0d1c27;box-shadow:0 0 30px #0c728744}.brand h1{font-size:19px;margin:0;letter-spacing:.2px}.brand p{margin:3px 0 0;color:#7f9aac;font-size:12px}.top-actions{display:flex;gap:9px;align-items:center}.badge,.download{font-size:12px;padding:7px 10px;border:1px solid #245a6e;border-radius:999px;background:#0d202b;color:#8fd7ef;text-decoration:none}.download:hover{border-color:#318aab;background:#103040}.stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-bottom:16px}.card,.panel{background:#0b141dcc;border:1px solid #1b2d3a;border-radius:14px;box-shadow:0 14px 50px #0004}.card{padding:14px}.label{color:#7f9aac;font-size:11px;text-transform:uppercase;letter-spacing:.09em}.value{font-size:25px;font-weight:700;margin-top:4px}.grid{display:grid;grid-template-columns:340px 1fr;gap:14px;min-height:650px}.panel{overflow:hidden}.panel-head{padding:14px 16px;border-bottom:1px solid #1b2d3a;display:flex;justify-content:space-between;align-items:center}.panel-head strong{font-size:13px}.muted{color:#708899;font-size:11px}.search{padding:11px;border-bottom:1px solid #172834;display:flex;gap:7px}.search input{width:100%;background:#071018;color:#dceaf2;border:1px solid #203b4c;border-radius:9px;padding:9px 10px;outline:none}.search input:focus{border-color:#2c8cb3}.search button{border:1px solid #2b6f8a;background:#103349;color:#ccefff;border-radius:9px;padding:0 12px;cursor:pointer}.search-results{border-bottom:1px solid #172834;max-height:240px;overflow:auto}.result{padding:10px 14px;border-bottom:1px solid #10202a;cursor:pointer}.result:hover{background:#102532}.result strong{display:block;font:12px ui-monospace,SFMono-Regular,Menlo,monospace;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.result span{font-size:10px;color:#748d9e}.sessions{max-height:700px;overflow:auto}.session{padding:14px 16px;border-bottom:1px solid #14232e;cursor:pointer;transition:.15s}.session:hover,.session.active{background:#102532}.session .sid{font:600 12px ui-monospace,SFMono-Regular,Menlo,monospace;overflow:hidden;text-overflow:ellipsis}.session .meta{color:#7992a4;font-size:11px;margin-top:6px;display:flex;gap:8px;flex-wrap:wrap}.content{display:grid;grid-template-rows:auto 1fr}.traces{display:flex;gap:8px;overflow:auto;padding:12px;border-bottom:1px solid #1b2d3a}.trace-chip{white-space:nowrap;border:1px solid #244353;background:#0d1b24;color:#b8ccd8;border-radius:9px;padding:8px 10px;font:11px ui-monospace,SFMono-Regular,Menlo,monospace;cursor:pointer}.trace-chip.active{border-color:#2b8ab0;background:#113044;color:#d7f3ff}.trace-detail{padding:18px;overflow:auto}.empty{height:360px;display:grid;place-items:center;color:#607889;text-align:center}.trace-title{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:18px}.trace-title code{font-size:12px;color:#8fd7ef}.waterfall{position:relative}.span{display:grid;grid-template-columns:220px 1fr 90px;gap:12px;align-items:center;padding:9px 0;border-bottom:1px solid #13232e}.span-name{font:12px ui-monospace,SFMono-Regular,Menlo,monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.bar-space{height:18px;background:#0a1118;border-radius:6px;position:relative;overflow:hidden}.bar{position:absolute;top:3px;height:12px;border-radius:5px;background:linear-gradient(90deg,#1e819f,#38b7d1);min-width:3px}.duration{text-align:right;color:#8aa2b3;font:11px ui-monospace,SFMono-Regular,Menlo,monospace}.attrs{margin-top:20px;display:grid;gap:10px}.span-card{border:1px solid #172d3a;border-radius:10px;padding:12px;background:#09131b}.span-card summary{cursor:pointer;font:12px ui-monospace,SFMono-Regular,Menlo,monospace;color:#c9dbe5}.kv{margin-top:10px;display:grid;grid-template-columns:220px 1fr;gap:5px 10px;font-size:11px}.kv kbd{color:#7f9aac;font:11px ui-monospace,SFMono-Regular,Menlo,monospace}.kv code{color:#c6d7e1;overflow-wrap:anywhere}.safe{color:#67d8a0}.error{color:#ff9d9d}@media(max-width:1050px){.stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.sessions{max-height:280px}.span{grid-template-columns:130px 1fr 70px}.kv{grid-template-columns:1fr}.top{align-items:flex-start}.top-actions{flex-direction:column;align-items:flex-end}}
</style>
</head>
<body>
<div class="shell">
  <div class="top"><div class="brand"><div class="mark">TF</div><div><h1>KARZOUN TraceForge</h1><p>Privacy-first AI coding-agent observability</p></div></div><div class="top-actions"><a class="download" id="exportLink" href="/api/export.jsonl">Export sanitized JSONL</a><div class="badge" id="health">● checking pipeline</div></div></div>
  <div class="stats"><div class="card"><div class="label">Sessions</div><div class="value" id="sessionsCount">–</div></div><div class="card"><div class="label">Traces</div><div class="value" id="tracesCount">–</div></div><div class="card"><div class="label">Spans</div><div class="value" id="spansCount">–</div></div><div class="card"><div class="label">Tasks</div><div class="value" id="tasksCount">–</div></div><div class="card"><div class="label">Privacy findings</div><div class="value" id="privacyCount">–</div></div></div>
  <div class="grid">
    <section class="panel"><div class="panel-head"><strong>Sessions & search</strong><span class="muted">sanitized data</span></div><div class="search"><input id="searchInput" type="search" placeholder="span, task, agent, attribute…" autocomplete="off"><button id="searchButton">Search</button></div><div class="search-results" id="searchResults" hidden></div><div class="sessions" id="sessions"></div></section>
    <section class="panel content"><div class="traces" id="traces"><span class="muted">Select a session</span></div><div class="trace-detail" id="detail"><div class="empty"><div><strong>No trace selected</strong><br><span class="muted">Generate a demo session or send OTLP through the privacy gateway.</span></div></div></div></section>
  </div>
</div>
<script>
const $=s=>document.querySelector(s);let activeSession=null,activeTrace=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ms=ns=>(Number(ns)/1e6).toFixed(Number(ns)>1e9?0:2)+' ms';
const fragment=new URLSearchParams(location.hash.startsWith('#')?location.hash.slice(1):location.hash);
const fragmentToken=fragment.get('token');if(fragmentToken){sessionStorage.setItem('traceforge_viewer_token',fragmentToken);history.replaceState(null,'',location.pathname+location.search)}
const viewerToken=()=>sessionStorage.getItem('traceforge_viewer_token');
const requestHeaders=accept=>{const h={'Accept':accept};const t=viewerToken();if(t)h['Authorization']='Bearer '+t;return h};
async function api(path){const r=await fetch(path,{headers:requestHeaders('application/json')});if(r.status===401)throw new Error('401 authorization required');if(!r.ok)throw new Error(`${r.status} ${r.statusText}`);return r.json()}
async function exportJsonl(e){e.preventDefault();try{const r=await fetch('/api/export.jsonl',{headers:requestHeaders('application/x-ndjson')});if(!r.ok)throw new Error(`${r.status} ${r.statusText}`);const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='traceforge-sanitized-spans.jsonl';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}catch(err){$('#health').textContent='● export authorization required';$('#health').className='badge error'}}
async function refresh(){try{const [stats,sessions]=await Promise.all([api('/api/stats'),api('/api/sessions')]);$('#health').textContent='● sanitized pipeline online';$('#health').className='badge safe';$('#sessionsCount').textContent=stats.sessions;$('#tracesCount').textContent=stats.traces;$('#spansCount').textContent=stats.spans;$('#tasksCount').textContent=stats.tasks;$('#privacyCount').textContent=stats.privacy_findings||0;renderSessions(sessions);if(!activeSession&&sessions.length)selectSession(sessions[0].session_id)}catch(e){$('#health').textContent='● viewer unavailable';$('#health').className='badge error'}}
function renderSessions(items){$('#sessions').innerHTML=items.map(s=>`<div class="session ${s.session_id===activeSession?'active':''}" data-id="${esc(s.session_id)}"><div class="sid">${esc(s.session_id)}</div><div class="meta"><span>${s.trace_count} trace${s.trace_count===1?'':'s'}</span><span>${s.span_count} spans</span><span>${esc(s.agent_name||'agent')}</span></div></div>`).join('')||'<div class="empty">No sessions yet</div>';document.querySelectorAll('.session').forEach(n=>n.onclick=()=>selectSession(n.dataset.id))}
async function selectSession(id){activeSession=id;activeTrace=null;document.querySelectorAll('.session').forEach(n=>n.classList.toggle('active',n.dataset.id===id));const traces=await api('/api/sessions/'+encodeURIComponent(id)+'/traces');$('#traces').innerHTML=traces.map(t=>`<button class="trace-chip" data-id="${t.trace_id}">${t.trace_id.slice(0,12)} · ${t.span_count} spans</button>`).join('')||'<span class="muted">No traces</span>';document.querySelectorAll('.trace-chip').forEach(n=>n.onclick=()=>selectTrace(n.dataset.id));if(traces.length)selectTrace(traces[0].trace_id)}
async function selectTrace(id){activeTrace=id;document.querySelectorAll('.trace-chip').forEach(n=>n.classList.toggle('active',n.dataset.id===id));const trace=await api('/api/traces/'+encodeURIComponent(id));renderTrace(trace)}
function renderTrace(t){const total=Math.max(1,t.end_ns-t.start_ns);const spans=t.spans.map(s=>{const left=((s.start_ns-t.start_ns)/total)*100,width=Math.max(.4,(s.duration_ns/total)*100);return `<div class="span"><div class="span-name" title="${esc(s.name)}">${esc(s.name)}</div><div class="bar-space"><div class="bar" style="left:${left}%;width:${Math.min(width,100-left)}%"></div></div><div class="duration">${ms(s.duration_ns)}</div></div>`}).join('');const cards=t.spans.map(s=>`<details class="span-card"><summary>${esc(s.name)} · ${s.span_id}</summary><div class="kv">${Object.entries(s.attributes||{}).map(([k,v])=>`<kbd>${esc(k)}</kbd><code>${esc(typeof v==='string'?v:JSON.stringify(v))}</code>`).join('')||'<span class="muted">No attributes</span>'}</div></details>`).join('');$('#detail').innerHTML=`<div class="trace-title"><div><div class="label">Trace</div><code>${t.trace_id}</code></div><div class="muted">${t.spans.length} spans · ${ms(total)}</div></div><div class="waterfall">${spans}</div><div class="attrs">${cards}</div>`}
async function searchSpans(){const q=$('#searchInput').value.trim(),box=$('#searchResults');if(!q){box.hidden=true;box.innerHTML='';return}try{const items=await api('/api/search?q='+encodeURIComponent(q)+'&limit=50');box.hidden=false;box.innerHTML=items.map(s=>`<div class="result" data-trace="${s.trace_id}"><strong>${esc(s.name)}</strong><span>${esc(s.session_id||'no session')} · ${s.trace_id.slice(0,12)} · ${ms(s.duration_ns)}</span></div>`).join('')||'<div class="result"><span>No sanitized matches</span></div>';box.querySelectorAll('[data-trace]').forEach(n=>n.onclick=()=>selectTrace(n.dataset.trace))}catch(e){box.hidden=false;box.innerHTML='<div class="result"><span>Search unavailable</span></div>'}}
$('#exportLink').onclick=exportJsonl;$('#searchButton').onclick=searchSpans;$('#searchInput').addEventListener('keydown',e=>{if(e.key==='Enter')searchSpans()});
refresh();setInterval(refresh,15000);
</script>
</body>
</html>'''
